create table if not exists public.expense_type(expense_type_id bigint generated always as identity primary key,type_name text not null unique,account_id bigint not null references public.chart_accounts(account_id),requires_receipt boolean not null default false);
create table if not exists public.expense_policy(policy_id bigint generated always as identity primary key,policy_name text not null,subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),max_amount_per_expense numeric(24,6) not null check(max_amount_per_expense>=0),unique(policy_name,subsidiary_id));
create table if not exists public.expense(expense_id bigint generated always as identity primary key,expense_number text not null unique,employee_id bigint not null references public.employees(employee_id),subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),currency_id bigint not null references public.currencies(currency_id),total_amount numeric(24,6) not null check(total_amount>=0),status_id bigint not null references public.status(status_id));
create table if not exists public.expense_line(expense_line_id bigint generated always as identity primary key,expense_id bigint not null references public.expense(expense_id) on delete cascade,expense_type_id bigint not null references public.expense_type(expense_type_id),amount numeric(24,6) not null check(amount>=0),tax_amount numeric(24,6) not null default 0 check(tax_amount>=0),department_id bigint references public.departments(department_id),class_id bigint references public.classes(class_id));
create table if not exists public.expense_approval(approval_id bigint generated always as identity primary key,expense_id bigint not null references public.expense(expense_id) on delete cascade,approver_user_id bigint not null references public.users(user_id),approval_date date not null,status text not null);
create table if not exists public.expense_payment(payment_id bigint generated always as identity primary key,payment_date date not null,expense_id bigint not null references public.expense(expense_id),bank_account_id bigint not null references public.bank_account(bank_account_id),amount_paid numeric(24,6) not null check(amount_paid>0));
do $$declare t text;begin foreach t in array array['expense_type','expense_policy','expense','expense_line','expense_approval','expense_payment'] loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists "expenses_select" on public.%I',t);execute format('drop policy if exists "expenses_insert" on public.%I',t);execute format('drop policy if exists "expenses_update" on public.%I',t);execute format('drop policy if exists "expenses_delete" on public.%I',t);execute format('create policy "expenses_select" on public.%I for select to authenticated using(true)',t);execute format('create policy "expenses_insert" on public.%I for insert to authenticated with check(true)',t);execute format('create policy "expenses_update" on public.%I for update to authenticated using(true) with check(true)',t);execute format('create policy "expenses_delete" on public.%I for delete to authenticated using(true)',t);end loop;end$$;
